"use client";
import React from 'react';
import { useRouter } from 'next/navigation';

export default function Home() {
  const router = useRouter();

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const name = formData.get('name');
    console.log('Submitted name:', name);
  };

  return (
    <div className='flex flex-col items-center justify-center min-h-screen bg-red-400 text-white'>
      <h1 className='text-4xl font-bold mb-8'>hi lekhar</h1>
      <div className='flex w-full max-w-4xl'>
        <section className='flex-1 p-4 bg-gray-800 rounded-l'>Hi</section>
        <section className='flex-1 p-4 bg-gray-800 rounded-r'>Lopa</section>
      </div>
      <button
        className='mt-4 px-4 py-2 bg-green-600 hover:bg-green-700 rounded'
        onClick={() => console.log('Button clicked')}
      >
        Click Me
      </button>
      <button
        className='mt-4 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded'
        onClick={() => console.log('next button clicked')}
      >
        next
      </button>
      <button
        className='mt-4 px-4 py-2 bg-yellow-600 hover:bg-yellow-700 rounded'
        onClick={() => router.push('/next')}
      >
        Next
      </button>
      <button
        className='mt-4 px-4 py-2 bg-purple-600 hover:bg-purple-700 rounded'
        onClick={() => router.push('/deploy')}
      >
        Deploy
      </button>
      <button
        className='mt-4 px-4 py-2 bg-indigo-600 hover:bg-indigo-700 rounded'
        onClick={() => console.log('next button clicked')}
      >
        next
      </button>
      <form onSubmit={handleSubmit} className='mt-4 w-full max-w-md'>
        <label className='block mb-2'>
          Name:
          <input
            type='text'
            name='name'
            className='mt-1 block w-full p-2 bg-gray-700 text-white rounded'
          />
        </label>
        <button
          type='submit'
          className='px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded'
        >
          Submit
        </button>
      </form>
    </div>
  );
}

